entries[44141] = { ["name"] = "Saat der Verderbnis", ["text"] = "550 Mana 30 Meter Reichweite\nWirken in 2 sek.\nPflanzt dem feindlichen Ziel einen Samen der Verderbnis ein, der 18 Sek. lang 1500 Schattenschaden verursacht. Wenn das Ziel insgesamt 2500 Schaden nimmt, verursacht der Samen bei allen Feinden im Umkreis von 10 Metern um das Ziel Schattenschaden." }
entries[44142] = { ["name"] = "Todesmantel", ["text"] = "200 Mana 30 Meter Reichweite\nSofort\nVerursacht 500 Schattenschaden und das betroffene Ziel läuft 3 Sek. lang voller Entsetzen davon. Der Zaubernde erhält 100% des verursachten Schadens in Gesundheit." }
