entries[44151] = { ["name"] = "Turbogetriebene Flugmaschine", ["text"] = "Wirken in 3 sek.\nBeschwört eine turbogetriebene Flugmaschine und gibt sie wieder frei. Dies ist ein sehr schneller Flugapparat. Dieses Gefährt kann nur in der Scherbenwelt verwendet werden." }
entries[44153] = { ["name"] = "Flugmaschine", ["text"] = "Wirken in 3 sek.\nBeschwört eine Flugmaschine und gibt sie wieder frei. Dieses Gefährt kann nur in der Scherbenwelt verwendet werden." }
entries[44155] = { ["name"] = "Flugmaschine", ["text"] = "Wirken in 8 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nAdamantitrahmen (2), Teufelseisenbarren (30), Eine Hand voll Teufelseisenbolzen (8), Sternenholz (8), Adamantitbarren (5), Elementare Zephyriumladung (4)\nEine unglaubliche Maschine, die es dem Ingenieur ermöglicht, in der Scherbenwelt zu fliegen.\nSteuerung für eine Flugmaschine\nWird bei Benutzung gebunden\nReittier\n70\nBenötigt Ingenieurskunst\n(350)\nBenutzen: Beschwört eine Flugmaschine und gibt sie wieder frei. Dieses Gefährt kann nur in der Scherbenwelt verwendet werden. (3 Sek. Abklingzeit)\n\"Für die Benutzung wird die Fähigkeit 'Erfahrener Reiter' oder höher benötigt.\"" }
entries[44157] = { ["name"] = "Turbogetriebene Flugmaschine", ["text"] = "Wirken in 8 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nSteuerung für eine Flugmaschine , Khoriumkraftkern (8), Teufelsstahlstabilisator (8), Hula-Wackelpuppe\nEine unglaubliche Maschine, die es dem Ingenieur ermöglicht, in der Scherbenwelt zu fliegen. Dieses Modell ist turbogetrieben.\nSteuerung für eine turbogetriebene Flugmaschine\nWird bei Benutzung gebunden\nReittier\n70\nBenötigt Ingenieurskunst\n(375)\nBenutzen: Beschwört eine turbogetriebene Flugmaschine und gibt sie wieder frei. Dies ist ein sehr schneller Flugapparat. Dieses Gefährt kann nur in der Scherbenwelt verwendet werden. (3 Sek. Abklingzeit)\n\"Für die Benutzung wird die Fähigkeit 'Gekonnter Reiter' oder höher benötigt.\"" }
entries[44163] = { ["name"] = "Wichtel beschwören", ["text"] = "15% von Grundmana\nWirken in 5 sek.\nBeschwört einen Wichtel, der unter dem Befehl des Hexenmeisters steht." }
entries[44164] = { ["name"] = "Feuerblitz", ["text"] = "20 Mana 30 Meter Reichweite\nWirken in 1 sek.\nSchleudert einen Flammenblitz auf einen Feind und verursacht Feuerschaden." }
entries[44166] = { ["name"] = "Erfrischung", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. 7500 Gesundheit und 7200 Mana wieder her. Ihr müsst beim Essen sitzen bleiben." }
