entries[44174] = { ["name"] = "Erneuerung", ["text"] = "365 Mana 40 Meter Reichweite\nSofort\nHeilt das Ziel 15 Sek. lang um 2160 Schaden." }
entries[44175] = { ["name"] = "Machtwort: Schild", ["text"] = "500 Mana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 1455 Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 Sek. lang nicht wieder abgeschirmt werden." }
entries[44176] = { ["name"] = "Eislanze", ["text"] = "30 Meter Reichweite\nSofort\nFügt einem gegnerischen Ziel 438 bis 562 Frostschaden zu. Bei eingefrorenen Zielen wird dreifacher Schaden zugefügt." }
entries[44177] = { ["name"] = "Frostnova", ["text"] = "75 Mana\nSofort\nVerursacht Frostschaden bei in der Nähe befindlichen Feinden und macht sie bis zu 8 Sek. lang bewegungsunfähig." }
entries[44178] = { ["name"] = "Blizzard", ["text"] = "1400 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 8 sek.)\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 Sek. lang insgesamt 2672 Frostschaden." }
entries[44181] = { ["name"] = "Klingenwirbel", ["text"] = "100 Meter Reichweite\nSofort\nEure nächsten 0 Nahkampfwaffenschwünge treffen einen weiteren in der Nähe befindlichen Gegner." }
